mapper.update:
UPDATE registered_persons
SET name = #{name},
    relationship = #{relationship}
WHERE registered_person_id = #{registeredPersonId}
  AND user_id = #{userId}

UPDATE bank_accounts
SET bank_code = #{bankCode},
    bank_name = #{bankName},
    account_number = #{accountNumber},
    account_alias = #{accountAlias}
WHERE bank_account_id = #{accountId}
  AND user_id = #{userId}
  AND registered_person_id = #{registeredPersonId}

mapper.select:
SELECT transaction_id, transaction_type, transaction_category AS category, amount, counterparty_name, description, balance_after, transaction_at FROM transactions WHERE user_id = #{userId} AND bank_account_id = #{accountId}
AND transaction_category = #{category}
ORDER BY transaction_at DESC, transaction_id DESC
